#!/usr/bin/env python3
"""crispr/sge_library_design — auto-generated run.py (archetype=crispr).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "crispr"
BRAIN = "crispr"
SKILL = "sge_library_design"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'sge_library_design', 'n_guides': 0, 'guides_csv': '', 'best_guide': {'seq': '', 'cfd_score': 0.0, 'mit_score': 0.0}, 'diagnostics': {'brain': 'crispr', 'archetype': 'crispr'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Saturation Genome Editing library:per target codon × 20 amino acids variant。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    cds = payload.get("cds_sequence")
    target_codons = payload.get("target_codon_positions") or []  # 1-based
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_codons": len(target_codons)}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_guides": 0, "guides_csv": "",
                "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not cds or not target_codons:
        return {"ok": False, "error": "需要 cds_sequence + target_codon_positions",
                "diagnostics": diagnostics}
    # 20 amino acid → 1 codon mapping (common usage)
    codon_table = {"A": "GCC", "C": "TGC", "D": "GAC", "E": "GAG", "F": "TTC",
                   "G": "GGC", "H": "CAC", "I": "ATC", "K": "AAG", "L": "CTG",
                   "M": "ATG", "N": "AAC", "P": "CCC", "Q": "CAG", "R": "CGG",
                   "S": "TCC", "T": "ACC", "V": "GTG", "W": "TGG", "Y": "TAC"}
    cds_u = cds.upper()
    variants = []
    for pos in target_codons:
        start = (pos - 1) * 3
        if start + 3 > len(cds_u): continue
        wt = cds_u[start:start+3]
        for aa, codon in codon_table.items():
            if codon == wt: continue
            variants.append({"codon_position": pos, "wt_codon": wt, "mutant_aa": aa, "mutant_codon": codon})
    return {"ok": True, "skill_id": SKILL,
            "n_guides": len(variants), "guides_csv": "",
            "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
            "library_variants": variants, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
